			return nil, err
		}
		defer w8a8Mod.Destroy()
		for i, v := range coldW4A8Variants {
			if w4a8Mods[i], err = dev.NewShaderModule(v.spirv); err != nil {
				return nil, err
			}
			defer w4a8Mods[i].Destroy()
		}
