	row := func(label string, u, d pick) {
		// One MoE block per token: gate and up are two matrices of the gate_up
		// shape and down is one, each run for every expert the token routes to.
		block := float64(moeTopK) * (2*u.nsPerPair + d.nsPerPair)
		pass := float64(moeLayers) * block
		fmt.Fprintf(tw, "%s\\tt=%s/%s\\t%.2f/%.2f\\t%.1f us\\t%.1f us\\t%.3f ms\\t%.2f ms\\t%.0f\\t%s\\n",
