// Temporary: replay results/moe.csv through the summary printers.
func TestReplayMoE(t *testing.T) {
	f, err := os.Open("../results/moe.csv")
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	recs, err := csv.NewReader(f).ReadAll()
	if err != nil {
		t.Fatal(err)
	}
	var results []Result
	for _, rec := range recs[1:] {
		bs, _ := strconv.Atoi(rec[3])
		sz, _ := strconv.Atoi(rec[4])
		ns, _ := strconv.ParseFloat(rec[5], 64)
		gf, _ := strconv.ParseFloat(rec[6], 64)
		gb, _ := strconv.ParseFloat(rec[7], 64)
		results = append(results, Result{
			Op: rec[0], Variant: rec[1], WeightFormat: rec[2], BlockSize: bs, Size: sz,
			NsPerIter: ns, GFLOPS: gf, GBPS: gb, Detail: rec[12],
		})
	}
	PrintMoEGEMVSummary(os.Stdout, results)
}

