p='bench/ops_moe_gemv.go'
s=open(p).read()
old = '''// residency says whether this case's distinct weight bytes fit in the MALL, in
// which case the timing loop is measuring the cache and not the bus. It is a
// field rather than a footnote because at one token they do fit, and that is
// the trap §3.5's decode rows fell into.
func (c moeGEMVCase) residency() string {
	if c.touched < mallBytes {
		return "mall"
	}
	return "dram"
}'''
assert old in s
new = '''// residency says where this case's weights are coming from on the second and
// later iterations of the timing loop. It is a recorded field rather than a
// footnote because at one token they come from cache, and that is the trap
// §3.5's decode rows fell into.
//
// The three-way split, rather than a single 32 MiB threshold, is because the
// measurement showed the threshold is not where the cliff is: a 34 MB
// footprint — nominally larger than the cache — still reads 410 GB/s, 1.7x the
// bus, so the MALL is serving most of it. Only past about twice the cache does
// the rate fall to the bus and stay there. "edge" is the band in between, and
// nothing in a summary should treat it as a DRAM measurement.
func (c moeGEMVCase) residency() string {
	switch {
	case c.touched < mallBytes:
		return "mall"
	case c.touched < 2*mallBytes:
		return "edge"
	}
	return "dram"
}'''
s=s.replace(old,new,1)
old2 = '''	fmt.Fprintf(w, "  t=1 and t=4 touch less than the %d MB MALL and are cache-resident (the trap §3.5's decode\\n"+
		"  rows fell into); t=16 and t=64 are the DRAM measurements. COVER/ROW is §1.7's C against the\\n"+
		"  4-bit row: the rule says the bus is reached when they are equal\\n", mallBytes>>20)'''
assert old2 in s
new2 = '''	fmt.Fprintf(w, "  these are bytes *asked for*; where several pairs share an expert the MALL serves the\\n"+
		"  repeats, so only the t=16 and t=64 columns — which touch 3.5x and 9.4x the %d MB cache — are\\n"+
		"  DRAM rates. COVER/ROW is §1.7's C against the 4-bit row: the rule says the bus is reached when\\n"+
		"  they are equal\\n", mallBytes>>20)'''
s=s.replace(old2,new2,1)
open(p,'w').write(s)
print('ok')
